import {audioReport} from './browser-audio-core.js?v=20261027motion';
import {referenceAudioTask} from './breakdown.js?v=20261028wipe';
const $=id=>document.getElementById(id);let worker=null,pending=null,cancelled=false;
function stop(){worker?.terminate();worker=null;pending?.reject(Error('音频分析已停止'));pending=null}
$('browser-audio-stop').onclick=()=>{cancelled=true;stop()};
async function run(mode,selftest=false){let report;cancelled=false;try{$('browser-audio-stop').hidden=false;$('browser-audio-status').textContent='正在读取原视频音轨…';report=await referenceAudioTask(async({file,reference})=>{if(selftest){const response=await fetch('https://huggingface.co/datasets/Xenova/transformers.js-docs/resolve/main/jfk.wav');if(!response.ok)throw Error('官方公开语音示例下载失败');file=new File([await response.blob()],'official-speech-example.wav',{type:'audio/wav'});reference={name:'Hugging Face 官方公开语音示例'}}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('浏览器不支持音频解码');const context=new Audio();let buffer;try{buffer=await context.decodeAudioData(await file.arrayBuffer())}catch{throw Error('未能解码原视频音轨；可能没有音轨或编码不受支持')}finally{await context.close().catch(()=>{})}if(cancelled)throw Error('音频分析已停止');const offline=new OfflineAudioContext(1,Math.ceil(buffer.duration*16000),16000),source=offline.createBufferSource();source.buffer=buffer;source.connect(offline.destination);source.start();const mono=(await offline.startRendering()).getChannelData(0).slice();if(cancelled)throw Error('音频分析已停止');stop();worker=new Worker(new URL('./browser-ai-worker.js?v=20261027motion',import.meta.url),{type:'module'});return await new Promise((resolve,reject)=>{const timer=setTimeout(()=>stop(),600000);pending={reject:e=>{clearTimeout(timer);reject(e)}};worker.onmessage=({data})=>{if(data.type==='progress'){$('browser-audio-status').textContent=data.text;return}clearTimeout(timer);pending=null;if(data.type==='error')reject(Error(data.text));else if(data.type==='audio-result')resolve({...data.result,reference})};worker.onerror=()=>{clearTimeout(timer);pending=null;reject(Error('音频模型或浏览器运行失败；不会转用收费服务'))};worker.postMessage({type:'audio',mode,audio:mono},[mono.buffer])})},{example:selftest});const text=audioReport(report);$('browser-audio-output').textContent=text;if(!selftest){document.dispatchEvent(new CustomEvent('browser-audio-result',{detail:text}));document.dispatchEvent(new CustomEvent('browser-audio-evidence',{detail:report}));}$('browser-audio-status').textContent='音频模型已运行完成。下面是候选分类或自动转录，请听原声校对；不能识别原音效库名称或证明声音由后期加入。'}catch(error){$('browser-audio-status').textContent='音频分析未完成：'+error.message}finally{stop();$('browser-audio-stop').hidden=true}}
$('browser-audio-events').onclick=()=>run('events');$('browser-audio-speech').onclick=()=>run('speech');
document.addEventListener('reference-changed',()=>{$('browser-audio-output').textContent='';$('browser-audio-status').textContent='视频已更换，尚未运行音频分析。'});

$('browser-audio-selftest').onclick=()=>{$('tab-breakdown').click();document.querySelector('.browser-audio').scrollIntoView({behavior:'smooth',block:'start'});return run('speech',true)};
